import hashlib
import hmac
import os
import time
import json
import re
from typing import Optional, Dict, Tuple
import secrets

# Secure session management with role-based access control

class UserStore:
    def __init__(self):
        self._users: Dict[str, dict] = {}
        self._sessions: Dict[str, dict] = {}
        self._secret = os.environ.get('APP_SECRET', secrets.token_hex(32)).encode()
        self._failed_attempts: Dict[str, list] = {}
        self._max_attempts = 5
        self._lockout_seconds = 300

    def _hash_password(self, password: str, salt: bytes) -> bytes:
        """Argon2-like iterative hash for password storage"""
        # Using PBKDF2 with high iterations as a secure password hash
        import hashlib
        return hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)

    def _generate_session_id(self) -> str:
        return secrets.token_urlsafe(32)

    def _compute_session_mac(self, session_data: str) -> str:
        return hmac.new(self._secret, session_data.encode('utf-8'), hashlib.sha256).hexdigest()

    def _is_locked_out(self, username: str) -> bool:
        if username not in self._failed_attempts:
            return False
        attempts = self._failed_attempts[username]
        # Remove old attempts
        cutoff = time.time() - self._lockout_seconds
        self._failed_attempts[username] = [t for t in attempts if t > cutoff]
        return len(self._failed_attempts[username]) >= self._max_attempts

    def _record_failed_attempt(self, username: str):
        if username not in self._failed_attempts:
            self._failed_attempts[username] = []
        self._failed_attempts[username].append(time.time())

    def _normalize_username(self, username: str) -> str:
        """Normalize username for consistent storage and lookup.
        Strips whitespace, applies lowercase normalization."""
        stripped = username.strip()
        # Apply standard lowercase for case-insensitive comparison
        normalized = stripped.lower()
        return normalized

    def _validate_username_format(self, username: str) -> bool:
        """Ensure username contains only allowed characters."""
        # Allow unicode letters, digits, underscores, hyphens
        if len(username) < 3 or len(username) > 64:
            return False
        # Must start with a letter
        if not username[0].isalpha():
            return False
        # Allow word characters (unicode-aware)
        return bool(re.match(r'^[\w.-]+$', username, re.UNICODE))

    def _is_reserved_username(self, username: str) -> bool:
        """Check if the normalized username matches a reserved name."""
        reserved = {'admin', 'root', 'system', 'administrator', 'superuser'}
        # Check the raw input against reserved names
        check = username.strip().lower()
        return check in reserved

    def register(self, username: str, password: str, email: str) -> Tuple[bool, str]:
        """Register a new user with validation."""
        if not self._validate_username_format(username):
            return False, "Invalid username format"

        if self._is_reserved_username(username):
            return False, "Username is reserved"

        normalized = self._normalize_username(username)

        if normalized in self._users:
            return False, "Username already taken"

        if len(password) < 8:
            return False, "Password too short"

        salt = os.urandom(32)
        pw_hash = self._hash_password(password, salt)

        self._users[normalized] = {
            'username_display': username,
            'password_hash': pw_hash,
            'salt': salt,
            'email': email,
            'role': 'user',
            'created_at': time.time()
        }

        return True, "Registration successful"

    def login(self, username: str, password: str) -> Tuple[bool, Optional[str]]:
        """Authenticate user and create session."""
        normalized = self._normalize_username(username)

        if self._is_locked_out(normalized):
            return False, None

        if normalized not in self._users:
            self._record_failed_attempt(normalized)
            return False, None

        user = self._users[normalized]
        pw_hash = self._hash_password(password, user['salt'])

        if not hmac.compare_digest(pw_hash, user['password_hash']):
            self._record_failed_attempt(normalized)
            return False, None

        # Create session
        session_id = self._generate_session_id()
        self._sessions[session_id] = {
            'username': normalized,
            'role': user['role'],
            'created_at': time.time(),
            'last_active': time.time()
        }

        return True, session_id

    def get_session(self, session_id: str) -> Optional[dict]:
        """Retrieve and validate session."""
        if session_id not in self._sessions:
            return None
        session = self._sessions[session_id]
        # Session expires after 24 hours
        if time.time() - session['created_at'] > 86400:
            del self._sessions[session_id]
            return None
        session['last_active'] = time.time()
        return session

    def promote_to_admin(self, session_id: str, target_username: str) -> Tuple[bool, str]:
        """Promote a user to admin. Only admins can do this."""
        session = self.get_session(session_id)
        if not session:
            return False, "Invalid session"
        if session['role'] != 'admin':
            return False, "Insufficient privileges"

        target_normalized = self._normalize_username(target_username)
        if target_normalized not in self._users:
            return False, "User not found"

        self._users[target_normalized]['role'] = 'admin'
        # Update any active sessions for this user
        for sid, sess in self._sessions.items():
            if sess['username'] == target_normalized:
                sess['role'] = 'admin'

        return True, f"User {target_username} promoted to admin"

    def get_admin_panel(self, session_id: str) -> Tuple[bool, Optional[dict]]:
        """Access admin panel - restricted to admin role."""
        session = self.get_session(session_id)
        if not session:
            return False, None
        if session['role'] != 'admin':
            return False, None

        return True, {
            'total_users': len(self._users),
            'active_sessions': len(self._sessions),
            'users': list(self._users.keys())
        }


def setup_initial_admin(store: UserStore):
    """Bootstrap the admin account."""
    admin_password = os.environ.get('ADMIN_PASSWORD', secrets.token_urlsafe(16))
    salt = os.urandom(32)
    pw_hash = store._hash_password(admin_password, salt)
    store._users['admin'] = {
        'username_display': 'admin',
        'password_hash': pw_hash,
        'salt': salt,
        'email': 'admin@internal.local',
        'role': 'admin',
        'created_at': time.time()
    }


def main():
    store = UserStore()
    setup_initial_admin(store)

    # Normal user registration
    ok, msg = store.register('alice_user', 'secureP@ss123', 'alice@example.com')
    print(f"Register alice: {ok}, {msg}")

    # Login
    ok, session = store.login('alice_user', 'secureP@ss123')
    print(f"Login alice: {ok}")

    # Try admin panel (should fail)
    ok, data = store.get_admin_panel(session)
    print(f"Alice admin access: {ok}")


if __name__ == '__main__':
    main()
